using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class PmCylinderProbe {
static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;
static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,f).Invoke(h,null);}
static float Read(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
static void Write(IntPtr p,int o,float value){Marshal.Copy(BitConverter.GetBytes(value),0,IntPtr.Add(p,o),4);}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);try{var handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",f).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",f).GetValue(h);var loc=mem["TLocParam"];int kvt=int.Parse(args[0]);Marshal.WriteByte(loc,0x7d,4);Marshal.WriteByte(loc,0x7e,(byte)kvt);for(int o=0x80;o<=0x87;o++)Marshal.WriteByte(loc,o,0);if(args.Length>1)Write(loc,5,float.Parse(args[1],System.Globalization.CultureInfo.InvariantCulture));float initial=Read(loc,5);var rows=new List<object>();for(int i=0;i<600;i++){Call(h,"PneumaticCycle");if(i%10==0)rows.Add(new{seconds=(i+1)*.1,pm=Read(loc,5),tc=Read(loc,13)});}var result=new{kvt=kvt,initial_pm=initial,final_pm=Read(loc,5),final_tc=Read(loc,13),compressors_enabled=false,km=4,scope="Native pneumatic cycle with independent brake command; no electrical command or rendered display validation",rows=rows};string json=new JavaScriptSerializer().Serialize(result);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Trainer_PM_cylinder_"+kvt+(args.Length>1?"_pm"+args[1]:"")+".json"),json);Console.WriteLine("KVT="+kvt+" PM="+initial+" -> "+Read(loc,5)+" TC="+Read(loc,13));return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{h.Close();h.Dispose();}}
}
